pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address operator = address(0x123);
        vm.prank(address(this));
        c.initialize();
        // Set up roundImplementation and alloSettings to non-zero addresses
        vm.store(address(c), bytes32(uint256(1)), bytes32(uint256(0xdead)));
        vm.store(address(c), bytes32(uint256(2)), bytes32(uint256(0xbeef)));
        // Grant operator role
        vm.prank(address(this));
        c.updateRoundImplementation(payable(0x1111));
        vm.prank(address(this));
        c.updateAlloSettings(0x2222);
        // Now make operator a program operator
        vm.store(address(c), keccak256(abi.encode(operator, uint256(3))), bytes32(uint256(1)));
        // Try to call create as operator
        vm.prank(operator);
        bool ok;
        bytes memory empty;
        try c.create(empty, address(0x3333)) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
